$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
. (Join-Path $root 'validation/custom-app-promotion-eligibility-gate-v0.1.0/custom-app-promotion-eligibility.ps1')
. (Join-Path $root 'validation/custom-app-live-attested-production-admission-v0.1.0/custom-app-live-attested-production-admission.ps1')
. (Join-Path $root 'validation/custom-app-production-permit-v0.1.0/custom-app-production-permit.ps1')
. (Join-Path $PSScriptRoot 'custom-app-production-permit-reservation.ps1')

function Assert-True {param([bool]$Condition,[string]$Message)if(-not $Condition){throw $Message}}
function Assert-False {param([bool]$Condition,[string]$Message)if($Condition){throw $Message}}
function Copy-Deep {param($Object)return ($Object|ConvertTo-Json -Depth 40|ConvertFrom-Json)}
function Assert-NoExecutionAuthority {param($Result,[string]$Label)Assert-False ([bool]$Result.production_execution_authorized) "$Label production execution authority";Assert-False ([bool]$Result.production_mutation_authorized) "$Label production mutation authority";Assert-True ([bool]$Result.requires_atomic_compare_and_swap_persistence) "$Label CAS requirement missing"}

function New-ReservationFixture {
    param([string]$Name='tagify',[string]$Source='alexk218/tagify',[string]$Manifest='Tagify')
    $path=('C:\fixture\CustomApps\'+$Name);$localTree=('1'*64);$remoteTree=('2'*64);$provFp=('3'*64);$assetDigest=('4'*64);$commit=('a'*40);$observed='2026-10-28T10:30:00+00:00'
    $lifecycle=[pscustomobject]@{schema=1;managed_by='dynamic-spicetify-v1';kind='custom-app';name=$Name;present=$true;user_removed=$false;ambiguous=$false;safe_local_identity=$true;locations=@($path);mutation_mode='deny';auto_update_authorized=$false;auto_install_authorized=$false}
    $provenance=[pscustomobject]@{schema=1;managed_by='custom-app-provenance-v1';name=$Name;source_identity=$Source;last_proven_source=$Source;source_changed=$false;requires_reenrollment=$false;evidence_fingerprint=$provFp;mutation_mode='deny';auto_update_authorized=$false;auto_install_authorized=$false}
    $immutable=[pscustomobject]@{schema=1;managed_by='custom-app-remote-source-v1';source_identity=$Source;github_repo_id=[int64]987654321;surface_kind='release-asset';layout_root='.';manifest_name=$Manifest;last_verified_local_tree_sha256=$localTree;last_verified_remote_tree_sha256=$remoteTree;last_verified_commit_sha=$commit;release_asset_selector='unique-zip-asset';asset_name=($Name+'-v2.zip');last_observed_asset_id=[int64]418974188;last_observed_asset_digest_sha256=$assetDigest;mutation_mode='deny';auto_update_authorized=$false;auto_install_authorized=$false}
    $binding=[pscustomobject]@{schema=1;managed_by='custom-app-remote-binding-observer-v1';name=$Name;active=$true;source_identity=$Source;binding=$immutable;last_success=$observed;last_status='remote-change-observed';last_reason='verified-remote-runtime-change';last_error=$null;last_local_tree_sha256=$localTree;last_local_manifest_name=$Manifest;last_remote_tree_sha256=$remoteTree;last_remote_commit_sha=$commit;update_observed=$true;requires_reenrollment=$false;user_removed=$false;mutation_mode='deny';auto_update_authorized=$false;auto_install_authorized=$false}
    $baseline=[pscustomobject]@{safe=$true;installable=$true;tree_sha256=$localTree;manifest_name=$Manifest;path=$path}
    $shadow=[pscustomobject]@{schema=1;managed_by='custom-app-shadow-protocol-qualification-v1';validated_shadow_head=$CustomAppPromotionQualifiedShadowHead;validated_stage_parent=$CustomAppPromotionQualifiedStageHead;production_main=$CustomAppPromotionQualifiedProductionMain;addon_manager_sha256=$CustomAppPromotionQualifiedAddonSha256;spotify_control_sha256=$CustomAppPromotionQualifiedSpotifySha256;push_success=$true;pull_request_success=$true;offline_matrix_passed=$true;live_tagify_331_to_332_passed=$true;parent_selftest_passed=$true;push_run_id=$CustomAppPromotionQualifiedPushRunId;pull_request_run_id=$CustomAppPromotionQualifiedPrRunId;push_artifact_id=$CustomAppPromotionQualifiedPushArtifactId;pull_request_artifact_id=$CustomAppPromotionQualifiedPrArtifactId;push_artifact_digest=$CustomAppPromotionQualifiedPushArtifactDigest;pull_request_artifact_digest=$CustomAppPromotionQualifiedPrArtifactDigest;mutation_mode='deny';mutation_authorized=$false;auto_update_authorized=$false;auto_install_authorized=$false;canary_execution_authorized=$false;production_mutation_authorized=$false}
    return [pscustomobject]@{name=$Name;lifecycle=$lifecycle;provenance=$provenance;binding=$binding;baseline=$baseline;shadow=$shadow;live=(New-CustomAppLiveAttestedProtocolQualificationV010)}
}

$now=[DateTimeOffset]'2026-10-28T10:40:00+00:00';$key=[byte[]](1..32);$wrongKey=[byte[]](33..64)
function New-FixturePermit {param($F,[string]$Nonce='0123456789abcdef0123456789abcdef',[DateTimeOffset]$IssuedAt=$now)return New-CustomAppProductionPermitV010 -Name $F.name -LifecycleRow $F.lifecycle -ProvenanceRow $F.provenance -BindingRow $F.binding -CurrentBaseline $F.baseline -ShadowProtocolQualification $F.shadow -LiveAttestedQualification $F.live -SessionKey $key -Nonce $Nonce -IssuedAt $IssuedAt -TtlMinutes 3}
function Reserve-Fixture {param($Permit,$F,$State,[int64]$ExpectedRevision,[DateTimeOffset]$At=$now,[byte[]]$SessionKey=$key)return Invoke-CustomAppProductionPermitReservationV010 -Permit $Permit -Name $F.name -LifecycleRow $F.lifecycle -ProvenanceRow $F.provenance -BindingRow $F.binding -CurrentBaseline $F.baseline -ShadowProtocolQualification $F.shadow -LiveAttestedQualification $F.live -SessionKey $SessionKey -ReservationState $State -ExpectedRevision $ExpectedRevision -Now $At}
function Assert-Denied {param($Result,[string]$Label)Assert-False ([bool]$Result.ok) "$Label unexpectedly reserved";Assert-False ([bool]$Result.reservation_created) "$Label created reservation";Assert-NoExecutionAuthority $Result $Label}

$count=0
$state=New-CustomAppProductionPermitReservationStateV010;$check=Test-CustomAppProductionPermitReservationStateV010 $state;Assert-True ([bool]$check.ok) ('fresh state invalid: '+[string]$check.reason);Assert-True ([int64]$state.revision -eq 0 -and @($state.reservations).Count -eq 0) 'fresh state shape drifted';$count++

$f=New-ReservationFixture;$permit=New-FixturePermit $f;$r=Reserve-Fixture $permit $f $state 0;Assert-True ([bool]$r.ok) ('valid reservation denied: '+[string]$r.reason);Assert-True ([string]$r.reason -ceq 'production-permit-reserved-once') 'valid reason drifted';Assert-True ([bool]$r.reservation_created -and [int64]$r.state_revision_before -eq 0 -and [int64]$r.state_revision_after -eq 1) 'valid revision drifted';Assert-True (Test-CustomAppProductionReservationSha256V010 ([string]$r.reservation_id)) 'reservation id invalid';Assert-NoExecutionAuthority $r 'valid-reservation';Assert-True ([int64]$state.revision -eq 0) 'input state was mutated in place';$saved=$r.next_state;Assert-True ([bool](Test-CustomAppProductionPermitReservationStateV010 $saved).ok) 'saved next state invalid';$count++

$replay=Reserve-Fixture $permit $f $saved 1;Assert-Denied $replay 'same-token-replay';Assert-True ([string]$replay.reason -ceq 'permit-already-reserved-token') 'same token replay reason drifted';$count++
$stale=Reserve-Fixture $permit $f $saved 0;Assert-Denied $stale 'stale-revision';Assert-True ([string]$stale.reason -ceq 'reservation-state-revision-conflict') 'stale revision reason drifted';$count++

$pSameNonce=New-FixturePermit $f '0123456789abcdef0123456789abcdef' $now.AddSeconds(10);$sameNonce=Reserve-Fixture $pSameNonce $f $saved 1 $now.AddSeconds(10);Assert-Denied $sameNonce 'same-nonce-different-token';Assert-True ([string]$sameNonce.reason -ceq 'permit-already-reserved-nonce') 'same nonce reason drifted';$count++
$pUnique=New-FixturePermit $f 'fedcba9876543210fedcba9876543210' $now.AddSeconds(10);$unique=Reserve-Fixture $pUnique $f $saved 1 $now.AddSeconds(10);Assert-True ([bool]$unique.ok) ('unique second permit denied: '+[string]$unique.reason);Assert-True ([int64]$unique.next_state.revision -eq 2 -and @($unique.next_state.reservations).Count -eq 2) 'second reservation state drifted';Assert-NoExecutionAuthority $unique 'second-reservation';$count++

$future=New-ReservationFixture -Name 'future-app' -Source 'owner/future-app' -Manifest 'Future App';$futurePermit=New-FixturePermit $future '11111111111111111111111111111111';$futureState=New-CustomAppProductionPermitReservationStateV010;$futureR=Reserve-Fixture $futurePermit $future $futureState 0;Assert-True ([bool]$futureR.ok) ('generic future app reservation denied: '+[string]$futureR.reason);Assert-NoExecutionAuthority $futureR 'future-app';$count++

$wrong=Reserve-Fixture $permit $f (New-CustomAppProductionPermitReservationStateV010) 0 $now $wrongKey;Assert-Denied $wrong 'wrong-key';Assert-True ([string]$wrong.reason -ceq 'permit-hmac-mismatch') 'wrong key reason drifted';$count++
$fRemoved=New-ReservationFixture;$pRemoved=New-FixturePermit $fRemoved;$fRemoved.lifecycle.user_removed=$true;$fRemoved.lifecycle.present=$false;$x=Reserve-Fixture $pRemoved $fRemoved (New-CustomAppProductionPermitReservationStateV010) 0;Assert-Denied $x 'user-removed-after-issue';Assert-True ([string]$x.reason -like 'permit-current-admission-denied:*') 'user removal did not revalidate permit';$count++
$fDrift=New-ReservationFixture;$pDrift=New-FixturePermit $fDrift;$fDrift.baseline.tree_sha256=('8'*64);$x=Reserve-Fixture $pDrift $fDrift (New-CustomAppProductionPermitReservationStateV010) 0;Assert-Denied $x 'runtime-drift-after-issue';$count++
$expiredPermit=New-FixturePermit $f '22222222222222222222222222222222' $now.AddMinutes(-4);$x=Reserve-Fixture $expiredPermit $f (New-CustomAppProductionPermitReservationStateV010) 0;Assert-Denied $x 'expired-before-reserve';Assert-True ([string]$x.reason -ceq 'permit-expired') 'expired reservation reason drifted';$count++

$badOwner=New-CustomAppProductionPermitReservationStateV010;$badOwner.managed_by='other';$x=Reserve-Fixture $permit $f $badOwner 0;Assert-Denied $x 'bad-state-owner';Assert-True ([string]$x.reason -ceq 'reservation-state-owner-or-schema-mismatch') 'bad owner reason drifted';$count++
$badAuthority=New-CustomAppProductionPermitReservationStateV010;$badAuthority.production_execution_authorized=$true;$x=Reserve-Fixture $permit $f $badAuthority 0;Assert-Denied $x 'bad-state-authority';Assert-True ([string]$x.reason -ceq 'reservation-state-production_execution_authorized-true') 'bad authority reason drifted';$count++
$badCount=New-CustomAppProductionPermitReservationStateV010;$badCount.revision=[int64]1;$s=Test-CustomAppProductionPermitReservationStateV010 $badCount;Assert-False ([bool]$s.ok) 'revision/count mismatch accepted';Assert-True ([string]$s.reason -ceq 'reservation-state-revision-count-mismatch') 'revision/count mismatch reason drifted';$count++

$tampered=Copy-Deep $saved;$tampered.reservations[0].reservation_id=('9'*64);$s=Test-CustomAppProductionPermitReservationStateV010 $tampered;Assert-False ([bool]$s.ok) 'tampered reservation id accepted';Assert-True ([string]$s.reason -ceq 'reservation-row-id-mismatch') 'tampered row id reason drifted';$count++
$dup=Copy-Deep $saved;$row2=Copy-Deep $dup.reservations[0];$row2.state_revision_before=[int64]1;$row2.state_revision_after=[int64]2;$row2.reservation_id=$null;$row2.reservation_id=Get-CustomAppProductionReservationSha256V010 (Get-CustomAppProductionReservationMaterialV010 $row2);$dup.reservations=@($dup.reservations[0],$row2);$dup.revision=[int64]2;$s=Test-CustomAppProductionPermitReservationStateV010 $dup;Assert-False ([bool]$s.ok) 'duplicate token accepted';Assert-True ([string]$s.reason -ceq 'reservation-state-duplicate-token') 'duplicate token reason drifted';$count++

$fDet=New-ReservationFixture;$pDet=New-FixturePermit $fDet '33333333333333333333333333333333';$a=Reserve-Fixture $pDet $fDet (New-CustomAppProductionPermitReservationStateV010) 0;$b=Reserve-Fixture $pDet $fDet (New-CustomAppProductionPermitReservationStateV010) 0;Assert-True ([bool]$a.ok -and [bool]$b.ok) 'determinism fixtures failed';Assert-True ([string]$a.reservation_id -ceq [string]$b.reservation_id) 'reservation id nondeterministic for same snapshot/time';$count++

# The pure protocol cannot serialize two independent writers by itself. The persisted integration MUST CAS revision 0->1.
$fRace=New-ReservationFixture;$pRace1=New-FixturePermit $fRace '44444444444444444444444444444444';$pRace2=New-FixturePermit $fRace '55555555555555555555555555555555';$raceSnapshot=New-CustomAppProductionPermitReservationStateV010;$candidate1=Reserve-Fixture $pRace1 $fRace $raceSnapshot 0;$candidate2=Reserve-Fixture $pRace2 $fRace $raceSnapshot 0;Assert-True ([bool]$candidate1.ok -and [bool]$candidate2.ok) 'independent snapshot candidates should both be locally valid';Assert-True ([bool]$candidate1.requires_atomic_compare_and_swap_persistence -and [bool]$candidate2.requires_atomic_compare_and_swap_persistence) 'race candidates did not require CAS persistence';$afterPersist=$candidate1.next_state;$loser=Reserve-Fixture $pRace2 $fRace $afterPersist 0;Assert-Denied $loser 'cas-race-loser';Assert-True ([string]$loser.reason -ceq 'reservation-state-revision-conflict') 'CAS race loser reason drifted';$count++

Write-Host ('CUSTOM_APP_PRODUCTION_PERMIT_RESERVATION_MATRIX_PASS total='+$count)
